using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class StudentsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly StudentsController _controller;

    public StudentsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        SeedStudents();
        _controller = new StudentsController(_context);
    }

    private void SeedStudents()
    {
        _context.Students.AddRange(
            new Student { ID = 1, FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = new DateTime(2020, 9, 1) },
            new Student { ID = 2, FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = new DateTime(2021, 9, 1) },
            new Student { ID = 3, FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = new DateTime(2019, 9, 1) }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_NoParams_ReturnsViewWithAllStudentsOrderedByLastName()
    {
        var result = _controller.Index(null, null, null, null) as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(3, model.Count);
        Assert.Equal("Alexander", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Anand", model[2].LastName);
    }

    [Fact]
    public void Index_NameDescSort_ReturnsStudentsOrderedByLastNameDescending()
    {
        var result = _controller.Index("name_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Anand", model[0].LastName);
        Assert.Equal("Alonso", model[1].LastName);
        Assert.Equal("Alexander", model[2].LastName);
    }

    [Fact]
    public void Index_DateSort_ReturnsStudentsOrderedByEnrollmentDate()
    {
        var result = _controller.Index("Date", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Anand", model[0].LastName); // 2019
        Assert.Equal("Alexander", model[1].LastName); // 2020
        Assert.Equal("Alonso", model[2].LastName); // 2021
    }

    [Fact]
    public void Index_DateDescSort_ReturnsStudentsOrderedByEnrollmentDateDescending()
    {
        var result = _controller.Index("date_desc", null, null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal("Alonso", model[0].LastName); // 2021
        Assert.Equal("Alexander", model[1].LastName); // 2020
        Assert.Equal("Anand", model[2].LastName); // 2019
    }

    [Fact]
    public void Index_SearchByLastName_FiltersResults()
    {
        var result = _controller.Index(null, null, "Alex", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alexander", model[0].LastName);
    }

    [Fact]
    public void Index_SearchByFirstName_FiltersResults()
    {
        var result = _controller.Index(null, null, "Meredith", null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Alonso", model[0].LastName);
    }

    [Fact]
    public void Index_SearchStringResetsPage()
    {
        var result = _controller.Index(null, null, "Alex", 3) as ViewResult;

        // When searchString is provided, page resets to 1
        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Equal(1, model.PageIndex);
    }

    [Fact]
    public void Index_UsesCurrentFilterWhenSearchStringIsNull()
    {
        var result = _controller.Index(null, "Anand", null, null) as ViewResult;

        var model = Assert.IsType<PaginatedList<Student>>(result.Model);
        Assert.Single(model);
        Assert.Equal("Anand", model[0].LastName);
    }

    [Fact]
    public void Details_ValidId_ReturnsStudent()
    {
        // Need to add enrollments for Include to work
        var course = new Course { CourseID = 100, Title = "Test", Credits = 3, DepartmentID = 0 };
        _context.Courses.Add(course);
        _context.Enrollments.Add(new Enrollment { StudentID = 1, CourseID = 100, Grade = Grade.A });
        _context.SaveChanges();

        var result = _controller.Details(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithStudentHavingTodayDate()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal(DateTime.Today, student.EnrollmentDate);
    }

    [Fact]
    public void Create_Post_ValidStudent_AddsAndRedirects()
    {
        var student = new Student
        {
            FirstMidName = "New",
            LastName = "Student",
            EnrollmentDate = new DateTime(2023, 1, 15)
        };

        var result = _controller.Create(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(4, _context.Students.Count());
    }

    [Fact]
    public void Create_Post_DefaultDate_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Bad",
            LastName = "Date",
            EnrollmentDate = DateTime.MinValue
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.False(_controller.ModelState.IsValid);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Create_Post_DateBelow1753_AddsModelError()
    {
        var student = new Student
        {
            FirstMidName = "Old",
            LastName = "Timer",
            EnrollmentDate = new DateTime(1600, 1, 1)
        };

        var result = _controller.Create(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Edit(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_NonexistentId_ReturnsNotFound()
    {
        var result = _controller.Edit(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidStudent_UpdatesAndRedirects()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Carson Updated",
            LastName = "Alexander",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };
        // Detach tracked entity
        _context.ChangeTracker.Clear();

        var result = _controller.Edit(student) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var updated = _context.Students.Find(1);
        Assert.Equal("Carson Updated", updated.FirstMidName);
    }

    [Fact]
    public void Edit_Post_DefaultDate_ReturnsViewWithError()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = default
        };

        var result = _controller.Edit(student) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithStudent()
    {
        var result = _controller.Delete(1) as ViewResult;

        Assert.NotNull(result);
        var student = Assert.IsType<Student>(result.Model);
        Assert.Equal("Alexander", student.LastName);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Delete_Get_NonexistentId_ReturnsNotFound()
    {
        var result = _controller.Delete(999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesAndRedirects()
    {
        var result = _controller.DeleteConfirmed(1) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(2, _context.Students.Count());
        Assert.Null(_context.Students.Find(1));
    }

    public void Dispose()
    {
        _controller?.Dispose();
        _context?.Dispose();
    }
}

