using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class CoursesControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly CoursesController _controller;
    private readonly Mock<IWebHostEnvironment> _mockEnv;
    private readonly Mock<ILogger<CoursesController>> _mockLogger;

    public CoursesControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _mockEnv = new Mock<IWebHostEnvironment>();
        _mockEnv.Setup(e => e.WebRootPath).Returns(Path.GetTempPath());
        _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.GetTempPath());
        _mockLogger = new Mock<ILogger<CoursesController>>();
        SeedData();
        _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
    }

    private void SeedData()
    {
        var dept = new Department { DepartmentID = 1, Name = "Engineering", Budget = 100000, StartDate = DateTime.Now };
        _context.Departments.Add(dept);
        _context.Courses.AddRange(
            new Course { CourseID = 1001, Title = "Chemistry", Credits = 3, DepartmentID = 1 },
            new Course { CourseID = 1002, Title = "Physics", Credits = 4, DepartmentID = 1 }
        );
        _context.SaveChanges();
    }

    [Fact]
    public void Index_ReturnsViewWithAllCourses()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
        var model = Assert.IsAssignableFrom<List<Course>>(result.Model);
        Assert.Equal(2, model.Count);
    }

    [Fact]
    public void Details_ValidId_ReturnsCourse()
    {
        var result = _controller.Details(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
        Assert.NotNull(course.Department);
    }

    [Fact]
    public void Details_NullId_ReturnsBadRequest()
    {
        var result = _controller.Details(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Create_Get_ReturnsViewWithDepartmentSelectList()
    {
        var result = _controller.Create() as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_ValidCourse_AddsAndRedirects()
    {
        var course = new Course { CourseID = 2000, Title = "Algebra", Credits = 3, DepartmentID = 1 };

        var result = _controller.Create(course, null) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Equal(3, _context.Courses.Count());
    }

    [Fact]
    public void Create_Post_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 3000, Credits = 3, DepartmentID = 1 };

        var result = _controller.Create(course, null) as ViewResult;

        Assert.NotNull(result);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Create_Post_WithInvalidFileExtension_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 3000, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFile("test.exe", 1024);

        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    }

    [Fact]
    public void Create_Post_WithOversizedFile_ReturnsViewWithError()
    {
        var course = new Course { CourseID = 3000, Title = "Test", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFile("test.jpg", 6 * 1024 * 1024); // 6MB

        var result = _controller.Create(course, mockFile.Object) as ViewResult;

        Assert.NotNull(result);
        Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        var errors = _controller.ModelState["teachingMaterialImage"].Errors;
        Assert.Contains("5MB", errors[0].ErrorMessage);
    }

    [Fact]
    public void Create_Post_WithValidImage_SavesFileAndRedirects()
    {
        var course = new Course { CourseID = 3000, Title = "Test Course", Credits = 3, DepartmentID = 1 };
        var mockFile = CreateMockFile("photo.png", 1024);

        var result = _controller.Create(course, mockFile.Object) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var saved = _context.Courses.Find(3000);
        Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
    }

    [Fact]
    public void Edit_Get_ValidId_ReturnsViewWithCourse()
    {
        var result = _controller.Edit(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
        Assert.NotNull(_controller.ViewBag.DepartmentID);
    }

    [Fact]
    public void Edit_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Edit(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void Edit_Get_NonexistentId_ReturnsNotFound()
    {
        var result = _controller.Edit(9999) as NotFoundResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Edit_Post_ValidCourse_UpdatesAndRedirects()
    {
        var course = new Course { CourseID = 1001, Title = "Chemistry Advanced", Credits = 4, DepartmentID = 1 };
        _context.ChangeTracker.Clear();

        var result = _controller.Edit(course, null) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        var updated = _context.Courses.Find(1001);
        Assert.Equal("Chemistry Advanced", updated.Title);
        Assert.Equal(4, updated.Credits);
    }

    [Fact]
    public void Edit_Post_InvalidModel_ReturnsView()
    {
        _controller.ModelState.AddModelError("Title", "Required");
        var course = new Course { CourseID = 1001, Credits = 3, DepartmentID = 1 };

        var result = _controller.Edit(course, null) as ViewResult;

        Assert.NotNull(result);
    }

    [Fact]
    public void Delete_Get_ValidId_ReturnsViewWithCourse()
    {
        var result = _controller.Delete(1001) as ViewResult;

        Assert.NotNull(result);
        var course = Assert.IsType<Course>(result.Model);
        Assert.Equal("Chemistry", course.Title);
    }

    [Fact]
    public void Delete_Get_NullId_ReturnsBadRequest()
    {
        var result = _controller.Delete(null) as StatusCodeResult;

        Assert.NotNull(result);
        Assert.Equal(400, result.StatusCode);
    }

    [Fact]
    public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
    {
        var result = _controller.DeleteConfirmed(1001) as RedirectToActionResult;

        Assert.NotNull(result);
        Assert.Equal("Index", result.ActionName);
        Assert.Null(_context.Courses.Find(1001));
    }

    private static Mock<IFormFile> CreateMockFile(string fileName, long length)
    {
        var mock = new Mock<IFormFile>();
        mock.Setup(f => f.FileName).Returns(fileName);
        mock.Setup(f => f.Length).Returns(length);
        mock.Setup(f => f.CopyTo(It.IsAny<Stream>()));
        return mock;
    }

    public void Dispose()
    {
        _controller?.Dispose();
        _context?.Dispose();
    }
}

