using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _controller;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _controller = new NotificationsController(_context);
    }

    [Fact]
    public void GetNotifications_NoNotifications_ReturnsEmptyList()
    {
        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        // The result is a JsonResult, check its value
        var value = result.Value;
        Assert.NotNull(value);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsUpTo10()
    {
        // Use a StudentsController to send notifications which enqueue to the shared queue
        var studentsController = new StudentsController(_context);
        for (int i = 0; i < 12; i++)
        {
            var student = new Student
            {
                FirstMidName = $"Student{i}",
                LastName = $"Last{i}",
                EnrollmentDate = new DateTime(2020, 1, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
        }

        // The notifications come from the shared static queue - they're produced
        // by SendEntityNotification calls. Let's directly use the notification service.
        var service = new Services.NotificationService();
        for (int i = 0; i < 12; i++)
        {
            service.SendNotification("Test", i.ToString(), EntityOperation.CREATE);
        }

        var result = _controller.GetNotifications();

        Assert.NotNull(result);
        var value = result.Value;
        Assert.NotNull(value);
        // Verify it returns data by checking the anonymous type
        var json = Newtonsoft.Json.JsonConvert.SerializeObject(value);
        Assert.Contains("\"success\":true", json);
        Assert.Contains("\"count\":", json);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccess()
    {
        var result = _controller.MarkAsRead(1);

        Assert.NotNull(result);
        var json = Newtonsoft.Json.JsonConvert.SerializeObject(result.Value);
        Assert.Contains("\"success\":true", json);
    }

    [Fact]
    public void Index_ReturnsView()
    {
        var result = _controller.Index() as ViewResult;

        Assert.NotNull(result);
    }

    public void Dispose()
    {
        _controller?.Dispose();
        _context?.Dispose();
    }
}

