using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests;

public class DbInitializerTests : IDisposable
{
    private readonly SchoolContext _context;

    public DbInitializerTests()
    {
        _context = TestDbContextFactory.Create();
    }

    [Fact]
    public void Initialize_EmptyDb_SeedsAllEntities()
    {
        DbInitializer.Initialize(_context);

        Assert.Equal(8, _context.Students.Count());
        Assert.Equal(5, _context.Instructors.Count());
        Assert.Equal(4, _context.Departments.Count());
        Assert.Equal(7, _context.Courses.Count());
        Assert.Equal(3, _context.OfficeAssignments.Count());
        Assert.Equal(8, _context.CourseAssignments.Count());
        Assert.True(_context.Enrollments.Count() >= 11);
    }

    [Fact]
    public void Initialize_AlreadySeeded_DoesNotDuplicate()
    {
        DbInitializer.Initialize(_context);
        var studentCountBefore = _context.Students.Count();

        DbInitializer.Initialize(_context);

        Assert.Equal(studentCountBefore, _context.Students.Count());
    }

    [Fact]
    public void Initialize_SeedsCorrectStudentData()
    {
        DbInitializer.Initialize(_context);

        var carson = _context.Students.Single(s => s.LastName == "Alexander");
        Assert.Equal("Carson", carson.FirstMidName);
        Assert.Equal(new DateTime(2010, 9, 1), carson.EnrollmentDate);
    }

    [Fact]
    public void Initialize_SeedsDepartmentsWithAdministrators()
    {
        DbInitializer.Initialize(_context);

        var english = _context.Departments.Single(d => d.Name == "English");
        Assert.NotNull(english.InstructorID);
        Assert.Equal(350000, english.Budget);
    }

    [Fact]
    public void Initialize_SeedsCoursesLinkedToDepartments()
    {
        DbInitializer.Initialize(_context);

        var chemistry = _context.Courses.Single(c => c.Title == "Chemistry");
        Assert.Equal(1050, chemistry.CourseID);
        Assert.Equal(3, chemistry.Credits);
        var dept = _context.Departments.Find(chemistry.DepartmentID);
        Assert.Equal("Engineering", dept.Name);
    }

    [Fact]
    public void Initialize_SeedsOfficeAssignments()
    {
        DbInitializer.Initialize(_context);

        var fakhouri = _context.Instructors.Single(i => i.LastName == "Fakhouri");
        var office = _context.OfficeAssignments.Find(fakhouri.ID);
        Assert.NotNull(office);
        Assert.Equal("Smith 17", office.Location);
    }

    [Fact]
    public void Initialize_SeedsEnrollmentsWithGrades()
    {
        DbInitializer.Initialize(_context);

        var alexander = _context.Students.Single(s => s.LastName == "Alexander");
        var enrollments = _context.Enrollments.Where(e => e.StudentID == alexander.ID).ToList();
        Assert.Equal(3, enrollments.Count);
        Assert.Contains(enrollments, e => e.Grade == Grade.A);
    }

    public void Dispose()
    {
        _context?.Dispose();
    }
}

