using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests;

public class ModelTests
{
    [Fact]
    public void Person_FullName_ReturnsConcatenatedName()
    {
        var student = new Student { FirstMidName = "John", LastName = "Doe" };

        Assert.Equal("Doe, John", student.FullName);
    }

    [Fact]
    public void Instructor_FullName_ReturnsConcatenatedName()
    {
        var instructor = new Instructor { FirstMidName = "Jane", LastName = "Smith" };

        Assert.Equal("Smith, Jane", instructor.FullName);
    }

    [Fact]
    public void Course_Properties_SetCorrectly()
    {
        var course = new Course
        {
            CourseID = 101,
            Title = "Chemistry",
            Credits = 4,
            DepartmentID = 1,
            TeachingMaterialImagePath = "/img/chem.png"
        };

        Assert.Equal(101, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(4, course.Credits);
        Assert.Equal(1, course.DepartmentID);
        Assert.Equal("/img/chem.png", course.TeachingMaterialImagePath);
    }

    [Fact]
    public void Course_NavigationProperties_DefaultToNull()
    {
        var course = new Course();

        Assert.Null(course.Department);
        Assert.Null(course.Enrollments);
        Assert.Null(course.CourseAssignments);
    }

    [Fact]
    public void Department_Properties_SetCorrectly()
    {
        var dept = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000m,
            StartDate = new DateTime(2007, 9, 1),
            InstructorID = 5,
            RowVersion = new byte[] { 1, 2, 3 }
        };

        Assert.Equal(1, dept.DepartmentID);
        Assert.Equal("Engineering", dept.Name);
        Assert.Equal(350000m, dept.Budget);
        Assert.Equal(new DateTime(2007, 9, 1), dept.StartDate);
        Assert.Equal(5, dept.InstructorID);
        Assert.Equal(new byte[] { 1, 2, 3 }, dept.RowVersion);
    }

    [Fact]
    public void Department_NavigationProperties_DefaultToNull()
    {
        var dept = new Department();

        Assert.Null(dept.Administrator);
        Assert.Null(dept.Courses);
    }

    [Fact]
    public void Enrollment_Properties_SetCorrectly()
    {
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 100,
            StudentID = 200,
            Grade = Grade.B
        };

        Assert.Equal(1, enrollment.EnrollmentID);
        Assert.Equal(100, enrollment.CourseID);
        Assert.Equal(200, enrollment.StudentID);
        Assert.Equal(Grade.B, enrollment.Grade);
    }

    [Fact]
    public void Enrollment_Grade_CanBeNull()
    {
        var enrollment = new Enrollment { EnrollmentID = 1 };

        Assert.Null(enrollment.Grade);
    }

    [Fact]
    public void CourseAssignment_Properties_SetCorrectly()
    {
        var ca = new CourseAssignment { InstructorID = 1, CourseID = 2 };

        Assert.Equal(1, ca.InstructorID);
        Assert.Equal(2, ca.CourseID);
        Assert.Null(ca.Instructor);
        Assert.Null(ca.Course);
    }

    [Fact]
    public void OfficeAssignment_Properties_SetCorrectly()
    {
        var oa = new OfficeAssignment { InstructorID = 5, Location = "Room 101" };

        Assert.Equal(5, oa.InstructorID);
        Assert.Equal("Room 101", oa.Location);
        Assert.Null(oa.Instructor);
    }

    [Fact]
    public void Instructor_Properties_SetCorrectly()
    {
        var instructor = new Instructor
        {
            ID = 1,
            FirstMidName = "Kim",
            LastName = "Abercrombie",
            HireDate = new DateTime(2000, 3, 15)
        };

        Assert.Equal(1, instructor.ID);
        Assert.Equal("Kim", instructor.FirstMidName);
        Assert.Equal("Abercrombie", instructor.LastName);
        Assert.Equal(new DateTime(2000, 3, 15), instructor.HireDate);
    }

    [Fact]
    public void Student_Properties_SetCorrectly()
    {
        var student = new Student
        {
            ID = 1,
            FirstMidName = "Carson",
            LastName = "Alexander",
            EnrollmentDate = new DateTime(2020, 9, 1)
        };

        Assert.Equal(1, student.ID);
        Assert.Equal("Carson", student.FirstMidName);
        Assert.Equal("Alexander", student.LastName);
        Assert.Equal(new DateTime(2020, 9, 1), student.EnrollmentDate);
    }

    [Fact]
    public void Notification_Properties_SetCorrectly()
    {
        var readAt = DateTime.Now;
        var notification = new Notification
        {
            Id = 1,
            EntityType = "Student",
            EntityId = "42",
            Operation = "CREATE",
            Message = "New student created",
            CreatedAt = new DateTime(2023, 1, 1),
            CreatedBy = "admin",
            IsRead = true,
            ReadAt = readAt
        };

        Assert.Equal(1, notification.Id);
        Assert.Equal("Student", notification.EntityType);
        Assert.Equal("42", notification.EntityId);
        Assert.Equal("CREATE", notification.Operation);
        Assert.Equal("New student created", notification.Message);
        Assert.Equal(new DateTime(2023, 1, 1), notification.CreatedAt);
        Assert.Equal("admin", notification.CreatedBy);
        Assert.True(notification.IsRead);
        Assert.Equal(readAt, notification.ReadAt);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
    [InlineData(Grade.C)]
    [InlineData(Grade.D)]
    [InlineData(Grade.F)]
    public void Grade_AllValues_AreValid(Grade grade)
    {
        var enrollment = new Enrollment { Grade = grade };
        Assert.Equal(grade, enrollment.Grade);
    }

    [Theory]
    [InlineData(EntityOperation.CREATE)]
    [InlineData(EntityOperation.UPDATE)]
    [InlineData(EntityOperation.DELETE)]
    public void EntityOperation_AllValues_AreValid(EntityOperation operation)
    {
        Assert.True(Enum.IsDefined(typeof(EntityOperation), operation));
    }
}

