using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using Xunit;

namespace ContosoUniversity.Tests;

public class SchoolContextTests : IDisposable
{
    private readonly SchoolContext _context;

    public SchoolContextTests()
    {
        _context = TestDbContextFactory.Create();
    }

    [Fact]
    public void Context_CanAddAndRetrieveStudentWithEnrollments()
    {
        var student = new Student { FirstMidName = "Test", LastName = "User", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        var course = new Course { CourseID = 500, Title = "Test Course", Credits = 3, DepartmentID = 0 };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var enrollment = new Enrollment { StudentID = student.ID, CourseID = 500, Grade = Grade.A };
        _context.Enrollments.Add(enrollment);
        _context.SaveChanges();

        var retrieved = _context.Enrollments.Include(e => e.Student).Include(e => e.Course).First();
        Assert.NotNull(retrieved.Student);
        Assert.NotNull(retrieved.Course);
        Assert.Equal("Test User", $"{retrieved.Student.FirstMidName} {retrieved.Student.LastName}");
        Assert.Equal("Test Course", retrieved.Course.Title);
    }

    [Fact]
    public void Context_CourseAssignment_CompositeKey_Works()
    {
        var instructor = new Instructor { FirstMidName = "A", LastName = "B", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        var course = new Course { CourseID = 600, Title = "Physics", Credits = 3, DepartmentID = 0 };
        _context.Courses.Add(course);
        _context.SaveChanges();

        var ca = new CourseAssignment { InstructorID = instructor.ID, CourseID = 600 };
        _context.CourseAssignments.Add(ca);
        _context.SaveChanges();

        var retrieved = _context.CourseAssignments.Find(600, instructor.ID);
        Assert.NotNull(retrieved);
    }

    [Fact]
    public void Context_InstructorWithOfficeAssignment_OneToOne()
    {
        var instructor = new Instructor { FirstMidName = "X", LastName = "Y", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var oa = new OfficeAssignment { InstructorID = instructor.ID, Location = "Room 42" };
        _context.OfficeAssignments.Add(oa);
        _context.SaveChanges();

        var retrieved = _context.Instructors.Include(i => i.OfficeAssignment).Single(i => i.ID == instructor.ID);
        Assert.NotNull(retrieved.OfficeAssignment);
        Assert.Equal("Room 42", retrieved.OfficeAssignment.Location);
    }

    [Fact]
    public void Context_StudentInheritsPerson()
    {
        var student = new Student { FirstMidName = "Derived", LastName = "Person", EnrollmentDate = DateTime.Now };
        _context.Students.Add(student);
        _context.SaveChanges();

        var person = _context.Students.First(s => s.LastName == "Person");
        Assert.Equal("Person, Derived", person.FullName);
        Assert.NotNull(person.Enrollments);
    }

    [Fact]
    public void Context_InstructorInheritsPerson()
    {
        var instructor = new Instructor { FirstMidName = "Teach", LastName = "Prof", HireDate = DateTime.Now, CourseAssignments = new List<CourseAssignment>() };
        _context.Instructors.Add(instructor);
        _context.SaveChanges();

        var retrieved = _context.Instructors.Include(i => i.CourseAssignments).First(i => i.LastName == "Prof");
        Assert.Equal("Prof, Teach", retrieved.FullName);
        Assert.NotNull(retrieved.CourseAssignments);
    }

    public void Dispose()
    {
        _context?.Dispose();
    }
}

