[Fact]
public void Context_StudentInheritsPerson()
{
    var student = new Student { FirstMidName = "Derived", LastName = "Person", EnrollmentDate = DateTime.Now, Enrollments = new List<Enrollment>() };
    _context.Students.Add(student);
    _context.SaveChanges();

    var person = _context.Students.Include(s => s.Enrollments).First(s => s.LastName == "Person");
    Assert.Equal("Person, Derived", person.FullName);
    Assert.NotNull(person.Enrollments);
}

